def find_tables(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'table' in k.lower() or 'ownership' in str(v).lower()[:100]:
                print(f'{path}.{k}')
            find_tables(v, f'{path}.{k}')
    elif isinstance(obj, list) and len(obj) > 0:
        find_tables(obj[0], f'{path}[0]')
find_tables(data)" 2>/dev/null | head -50

