def find_keys(obj, target=['ownership','securities','2000','2004'], path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if any(t in str(k).lower() for t in target):
                print(f'Key: {k}')
            find_keys(v, target, f'{path}.{k}')
    elif isinstance(obj, list) and len(obj) > 0:
        find_keys(obj[0], target, f'{path}[0]')
